/// Specification-only mathematical definition (inductive) of triangular numbers.
///
/// In plain Rust we encode it as a total recursive function over `u64`
/// (standing in for `nat`), suitable for reasoning/tests, not for large inputs.
fn triangle(n: u64) -> u64 {
    if n == 0 {
        0
    } else {
        n + triangle(n - 1)
    }
}

/// “Proof” placeholder in executable Rust:
/// establishes (by computation) that triangle is monotonic on a checked range.
///
/// Note: Rust has no native proof system; this function is a runtime check.
/// It can be used in tests or debug builds to gain confidence.
fn triangle_is_monotonic(i: u64, j: u64) {
    assert!(i <= j);
    assert!(triangle(i) <= triangle(j));
}

/// Tail-recursive procedure that updates `*sum` from triangle(idx) to triangle(n).
///
/// Assumptions (as in the problem statement):
/// - idx <= n
/// - *sum == triangle(idx)
/// - triangle(n) < 2^32 (so all intermediate additions fit in `u32`)
pub fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    // Tail recursion: each call increases idx by 1, so (n - idx) decreases by 1.
    fn go(n: u32, idx: u32, sum: &mut u32) {
        if idx == n {
            return;
        }
        let next_idx = idx + 1;
        *sum = sum
            .checked_add(next_idx)
            .expect("overflow: triangle(n) must fit in u32 per precondition");
        go(n, next_idx, sum);
    }

    assert!(idx <= n);
    go(n, idx, sum);
}